import os
import re
import json
import html as html_lib
import urllib.request
from html.parser import HTMLParser
from pathlib import Path
import subprocess
import sys
import time

URLS = [
    ("Do Things That Don't Scale", "https://paulgraham.com/ds.html"),
    ("Founder Mode", "https://paulgraham.com/foundermode.html"),
]

class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self.skip = False

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style", "noscript"):
            self.skip = True
        if tag in ("p", "br", "hr", "div", "tr", "li", "h1", "h2", "h3", "h4", "h5", "h6", "title"):
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag in ("script", "style", "noscript"):
            self.skip = False
        if tag in ("p", "div", "tr", "li"):
            self.parts.append("\n")

    def handle_data(self, data):
        if self.skip:
            return
        self.parts.append(data)


def fetch_html(url: str) -> str:
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    with urllib.request.urlopen(req) as resp:
        charset = resp.headers.get_content_charset() or "utf-8"
        return resp.read().decode(charset, errors="replace")


def extract_text(html: str) -> str:
    parser = TextExtractor()
    parser.feed(html)
    text = html_lib.unescape("".join(parser.parts))
    # Normalize line breaks
    lines = [ln.strip() for ln in text.splitlines()]
    # Drop obvious boilerplate lines
    drop_prefixes = (
        "©", "Copyright", "Translations", "RSS", "Email", "Share", "Back", "Home",
    )
    cleaned = []
    for ln in lines:
        if not ln:
            cleaned.append("")
            continue
        if ln.startswith(drop_prefixes):
            continue
        cleaned.append(ln)
    # Collapse multiple blank lines
    out_lines = []
    blank = False
    for ln in cleaned:
        if ln == "":
            if not blank:
                out_lines.append("")
            blank = True
        else:
            out_lines.append(ln)
            blank = False
    return "\n".join(out_lines).strip()


def split_text(text: str, max_chars: int = 3000):
    paras = [p.strip() for p in text.split("\n\n") if p.strip()]
    chunks = []
    cur = ""
    for p in paras:
        if not cur:
            cur = p
            continue
        if len(cur) + 2 + len(p) <= max_chars:
            cur = cur + "\n\n" + p
        else:
            chunks.append(cur)
            cur = p
    if cur:
        chunks.append(cur)
    # Fallback split for extremely long paragraphs
    final = []
    for c in chunks:
        if len(c) <= max_chars:
            final.append(c)
        else:
            for i in range(0, len(c), max_chars):
                final.append(c[i:i+max_chars])
    return final


def tts_request(text: str, out_path: Path, model: str):
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is not set")
    payload = {
        "model": model,
        "voice": "alloy",
        "format": "mp3",
        "input": text,
    }
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        "https://api.openai.com/v1/audio/speech",
        data=data,
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(req) as resp:
            out_path.write_bytes(resp.read())
            return True
    except urllib.error.HTTPError as e:
        err = e.read().decode("utf-8", errors="replace")
        print(f"TTS error ({model}): {e.code} {e.reason} - {err[:200]}")
        return False


workdir = Path("/root")
parts_dir = workdir / ".tts_parts"
parts_dir.mkdir(parents=True, exist_ok=True)

full_text_parts = []
for title, url in URLS:
    print(f"Fetching: {title}")
    html = fetch_html(url)
    body = extract_text(html)
    # Add a clear heading for TTS
    full_text_parts.append(f"{title}.\n\n{body}")

full_text = "\n\nEnd of essay.\n\n".join(full_text_parts)

chunks = split_text(full_text, max_chars=3000)
print(f"Total chunks: {len(chunks)}")

model_primary = "gpt-4o-mini-tts"
model_fallback = "tts-1"

part_files = []
for i, chunk in enumerate(chunks, start=1):
    out_path = parts_dir / f"part_{i:03d}.mp3"
    ok = tts_request(chunk, out_path, model_primary)
    if not ok:
        ok = tts_request(chunk, out_path, model_fallback)
    if not ok:
        raise RuntimeError(f"TTS failed for chunk {i}")
    part_files.append(out_path)
    time.sleep(0.2)

# Build concat list for ffmpeg
list_path = parts_dir / "concat.txt"
with list_path.open("w", encoding="utf-8") as f:
    for p in part_files:
        f.write(f"file '{p.as_posix()}'\n")

output = workdir / "audiobook.mp3"
subprocess.run([
    "ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", str(list_path), "-c", "copy", str(output)
], check=True)

print(f"Wrote {output}")
